{"command":"mkdir -p /tmp/work && cat > /tmp/work/helpers.py << 'PY'
import os, tempfile, shutil, subprocess
EXE="/workspace/executable"
def run_content(files_dict, args, label=""):
    tmp=tempfile.mkdtemp(dir="/tmp/work")
    try:
        for k,v in files_dict.items():
            if k.endswith("/"):
                os.makedirs(os.path.join(tmp,k),exist_ok=True); continue
            p=os.path.join(tmp,k)
            d=os.path.dirname(p)
            if d: os.makedirs(d,exist_ok=True)
            if isinstance(v,bytes): open(p,"wb").write(v)
            else: open(p,"w",encoding="utf-8",newline="").write(v)
        r=subprocess.run([EXE]+args,cwd=tmp,capture_output=True,text=True)
        lst=[]; contents={}
        for root,dirs,fnames in os.walk(tmp):
            for fn in fnames:
                rel=os.path.relpath(os.path.join(root,fn),tmp); lst.append(rel)
                try: contents[rel]=open(os.path.join(root,fn),encoding="utf-8").read()
                except: contents[rel]="<bin>"
            for dd in dirs: lst.append(os.path.relpath(os.path.join(root,dd),tmp)+"/")
        lst.sort()
        print(f"==={label} args={args} rc={r.returncode}\nstdout={r.stdout!r}\nstderr={r.stderr!r}\nfiles={lst}\ncontents={contents}\n")
        return r,tmp,contents
    except:
        shutil.rmtree(tmp,ignore_errors=True); raise
def done(tmp): shutil.rmtree(tmp,ignore_errors=True)

def run1(files,args,label=""):
    fdict=files if isinstance(files,dict) else {f:"X" for f in files}
    r,tmp,c=run_content(fdict,args,label); done(tmp); return r
