fn parse_opt() -> Opt {
    let m = build_cli().get_matches();
    let sort = m.get_one::<String>("sort").map(|s| {
        if s.eq_ignore_ascii_case("desc") {
            Order::Desc
        } else {
            Order::Asc
        }
    });
    Opt {
        dir: m.get_one::<PathBuf>("dir").cloned(),
        depth: m.get_one::<u64>("depth").map(|v| *v as usize),
        no_extension: m.get_flag("no-extension"),
        generate: m.get_one::<PathBuf>("generate").cloned(),
        mkdir: m.get_flag("mkdir"),
        map: m.get_one::<PathBuf>("map").cloned(),
        max_depth: m.get_one::<u64>("max-depth").map(|v| *v as usize),
        quiet: m.get_flag("quiet"),
        regex: m.get_one::<String>("regex").cloned(),
        sort,
        test: m.get_flag("test"),
        overwrite: m.get_flag("overwrite"),
        output: m
            .get_many::<String>("output")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
    }
}

// ---------- Errors ----------

enum AppError {
    Io(std::io::Error),
    Json(serde_json::Error),
    Regex(regex::Error),
    Msg(String),
    Fmt(FmtError),
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AppError::Io(e) => write!(f, "{}", e),
            AppError::Json(e) => write!(f, "{}", e),
            AppError::Regex(e) => write!(f, "{}", e),
            AppError::Msg(s) => write!(f, "{}", s),
            AppError::Fmt(e) => write!(f, "{}", e),
        }
    }
}

impl From<std::io::Error> for AppError {
    fn from(e: std::io::Error) -> Self {
        AppError::Io(e)
    }
}
impl From<serde_json::Error> for AppError {
    fn from(e: serde_json::Error) -> Self {
        AppError::Json(e)
    }
}
impl From<regex::Error> for AppError {
    fn from(e: regex::Error) -> Self {
        AppError::Regex(e)
    }
}
impl From<FmtError> for AppError {
    fn from(e: FmtError) -> Self {
        AppError::Fmt(e)
    }
}
impl From<String> for AppError {
    fn from(s: String) -> Self {
        AppError::Msg(s)
    }
}
impl From<&str> for AppError {
    fn from(s: &str) -> Self {
        AppError::Msg(s.to_owned())
    }
}

type AppResult<T> = Result<T, AppError>;

// ---------- Output formatter ----------

enum FmtError {
    MustBeSet,
    Unclosed,
    Unopened,
    InvalidEscape(char, usize),
    InvalidPadding(String),
}

impl fmt::Display for FmtError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            FmtError::MustBeSet => write!(f, "[output-format] output formatter must be set"),
            FmtError::Unclosed => write!(f, "[output-format] all opened placeholders must be closed by '}}'"),
            FmtError::Unopened => write!(f, "[output-format] an unopened placeholder could not be closed by '}}'"),
            FmtError::InvalidEscape(c, i) => write!(f, "[output-format] invalid escape character of '{}' at '{}'", c, i),
            FmtError::InvalidPadding(s) => write!(f, "[output-format] unable to parse padding of '{}'", s),
        }
    }
}

#[derive(Debug, Clone)]
enum Group {
    Index(usize),
    Name(String),
}

#[derive(Debug, Clone)]
enum Token {
    Text(String),
    Placeholder { group: Group, padding: Option<usize> },
}

#[derive(Debug, Clone)]
struct Formatter {
    tokens: Vec<Token>,
}

impl Formatter {
    fn new(pattern: Option<String>) -> Result<Self, FmtError> {
        let pattern = match pattern {
            Some(p) => p,
            None => return Err(FmtError::MustBeSet),
        };
        Self::parse(&pattern)
    }

    fn parse(pattern: &str) -> Result<Self, FmtError> {
        let mut tokens: Vec<Token> = Vec::new();
        let mut text = String::new();
        let mut placeholder: Option<String> = None;
        let mut auto: usize = 1;
        let mut chars = pattern.chars().enumerate().peekable();
        while let Some((idx, ch)) = chars.next() {
            match ch {
                '\\' => {
                    // Peek next char; peekable gives &(idx,ch)
                    if let Some(&(nidx, nch)) = chars.peek() {
                        if nch == '{' || nch == '}' || nch == '\\' {
                            chars.next();
                            match placeholder.as_mut() {
                                Some(buf) => buf.push(nch),
                                None => text.push(nch),
                            }
                        } else {
                            return Err(FmtError::InvalidEscape(nch, nidx));
                        }
                    } else {
                        // trailing backslash: ignore
                        let _ = idx;
                    }
                }
                '{' => {
                    if let Some(buf) = placeholder.as_mut() {
                        buf.push('{');
                    } else {
                        if !text.is_empty() {
                            tokens.push(Token::Text(std::mem::take(&mut text)));
                        }
                        placeholder = Some(String::new());
                    }
                }
                '}' => {
                    if let Some(buf) = placeholder.take() {
                        // parse buf: split at first ':'
                        let (group_str, padding) = match buf.find(':') {
                            Some(pos) => {
                                let g = &buf[..pos];
                                let p = &buf[pos + 1..];
                                if p.is_empty() {
                                    (g.to_owned(), None)
                                } else {
                                    match p.parse::<usize>() {
                                        Ok(v) => (g.to_owned(), Some(v)),
                                        Err(_) => {
                                            return Err(FmtError::InvalidPadding(p.to_owned()))
                                        }
                                    }
                                }
                            }
                            None => (buf, None),
                        };
                        let group = if group_str.is_empty() {
                            let g = Group::Index(auto);
                            auto += 1;
                            g
                        } else if let Ok(i) = group_str.parse::<usize>() {
                            Group::Index(i)
                        } else {
                            Group::Name(group_str)
                        };
                        tokens.push(Token::Placeholder { group, padding });
                    } else {
                        return Err(FmtError::Unopened);
                    }
                }
                _ => match placeholder.as_mut() {
                    Some(buf) => buf.push(ch),
                    None => text.push(ch),
                },
            }
        }
        if placeholder.is_some() {
            return Err(FmtError::Unclosed);
        }
        if !text.is_empty() {
            tokens.push(Token::Text(text));
        }
        Ok(Formatter { tokens })
    }

    fn format<F>(&self, mut resolve: F) -> String
    where
        F: FnMut(&Group) -> String,
    {
        let mut out = String::new();
        for tok in &self.tokens {
            match tok {
                Token::Text(t) => out.push_str(t),
                Token::Placeholder { group, padding } => {
                    let val = resolve(group);
                    match padding {
                        Some(p) => {
                            if let Ok(n) = val.parse::<u64>() {
                                out.push_str(&format!("{:0width$}", n, width = *p));
                            } else {
                                out.push_str(&val);
                            }
                        }
                        None => out.push_str(&val),
                    }
                }
            }
        }
        out
    }
}

// ---------- Natural sort ----------

fn nat_compare(a: &str, b: &str) -> Ordering {
    let av: Vec<char> = a.chars().collect();
    let bv: Vec<char> = b.chars().collect();
    let la = av.len();
    let lb = bv.len();
    let mut ia = 0usize;
    let mut ib = 0usize;
    loop {
        while ia < la && av[ia].is_whitespace() {
            ia += 1;
        }
        while ib < lb && bv[ib].is_whitespace() {
            ib += 1;
        }
        if ia >= la && ib >= lb {
            return Ordering::Equal;
        }
        if ia >= la {
            return Ordering::Less;
        }
        if ib >= lb {
            return Ordering::Greater;
        }
        let ca = av[ia];
        let cb = bv[ib];
        if ca.is_ascii_digit() && cb.is_ascii_digit() {
            if ca == '0' || cb == '0' {
                // fractional / left compare
                loop {
                    if ca != cb {
                        return ca.cmp(&cb);
                    }
                    // need mutable ca/cb copy - use inner loop with locals
                    break;
                }
                // Implement fractional with mutable locals
                let mut xa = ca;
                let mut xb = cb;
                loop {
                    if xa != xb {
                        return xa.cmp(&xb);
                    }
                    ia += 1;
                    ib += 1;
                    let a_digit = ia < la && av[ia].is_ascii_digit();
                    let b_digit = ib < lb && bv[ib].is_ascii_digit();
                    if a_digit && b_digit {
                        xa = av[ia];
                        xb = bv[ib];
                        continue;
                    }
                    if a_digit && !b_digit {
                        return Ordering::Greater;
                    }
                    if b_digit && !a_digit {
                        return Ordering::Less;
                    }
                    break;
                }
                continue;
            } else {
                let sa = ia;
                while ia < la && av[ia].is_ascii_digit() {
                    ia += 1;
                }
                let sb = ib;
                while ib < lb && bv[ib].is_ascii_digit() {
                    ib += 1;
                }
                let na = &av[sa..ia];
                let nb = &bv[sb..ib];
                if na.len() != nb.len() {
                    return na.len().cmp(&nb.len());
                }
                for i in 0..na.len() {
                    if na[i] != nb[i] {
                        return na[i].cmp(&nb[i]);
                    }
                }
                continue;
            }
        } else {
            if ca != cb {
                return ca.cmp(&cb);
            }
            ia += 1;
            ib += 1;
            continue;
        }
    }
}

// ---------- Helpers ----------

fn append_extension(formatted: &str, input: &str, preserve: bool) -> String {
    if !preserve {
        return formatted.to_owned();
    }
    match Path::new(input).extension() {
        Some(ext) => format!("{}.{}", formatted, ext.to_string_lossy()),
        None => formatted.to_owned(),
    }
}

type Entry = (String, String); // (input, output)

// ---------- Generators ----------

fn get_regex_entries(
    pattern_str: &str,
    output_pattern: Option<String>,
    depth_opt: Option<usize>,
    max_depth_opt: Option<usize>,
    no_extension: bool,
) -> AppResult<Vec<Entry>> {
    let re = Regex::new(pattern_str)?;
    let formatter = Formatter::new(output_pattern)?;
    let inferred = pattern_str.matches('/').count() + 1;
    let depth = depth_opt.unwrap_or(inferred);
    let max_eff = max_depth_opt.unwrap_or(depth);
    let min_eff = std::cmp::min(depth, max_eff);
    let mut entries: Vec<Entry> = Vec::new();
    for entry in WalkDir::new(".").min_depth(min_eff).max_depth(max_eff) {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let path = entry.path();
        let rel: String = match path.strip_prefix(".") {
            Ok(p) => p.to_string_lossy().into_owned(),
            Err(_) => path.to_string_lossy().into_owned(),
        };
        if let Some(caps) = re.captures(&rel) {
            let formatted = formatter.format(|g| resolve_capture(&caps, g));
            let out = append_extension(&formatted, &rel, !no_extension);
            entries.push((rel, out));
        }
    }
    Ok(entries)
}

fn resolve_capture(caps: &Captures<'_>, group: &Group) -> String {
    match group {
        Group::Index(i) => caps
            .get(*i)
            .map(|m| m.as_str().to_owned())
            .unwrap_or_default(),
        Group::Name(name) => caps
            .name(name)
            .map(|m| m.as_str().to_owned())
            .unwrap_or_default(),
    }
}

fn get_sort_entries(
    order: &Order,
    output_pattern: Option<String>,
    no_extension: bool,
) -> AppResult<Vec<Entry>> {
    let formatter = Formatter::new(output_pattern)?;
    let mut names: Vec<String> = Vec::new();
    for e in fs::read_dir(".")? {
        if let Ok(e) = e {
            names.push(e.file_name().to_string_lossy().into_owned());
        }
    }
    match order {
        Order::Asc => names.sort_by(|a, b| nat_compare(a, b)),
        Order::Desc => names.sort_by(|a, b| nat_compare(b, a)),
    }
    let mut entries: Vec<Entry> = Vec::new();
    for (i, name) in names.into_iter().enumerate() {
        let idx = (i + 1).to_string();
        let name_clone = name.clone();
        let formatted = formatter.format(|g| match g {
            Group::Index(0) => name_clone.clone(),
            Group::Index(1) => idx.clone(),
            _ => String::new(),
        });
        let out = append_extension(&formatted, &name, !no_extension);
        entries.push((name, out));
    }
    Ok(entries)
}

fn get_map_entries(map_path: &Path, output_pattern: Option<String>) -> AppResult<Vec<Entry>> {
    let content = fs::read_to_string(map_path)?;
    let parsed: HashMap<String, String> = serde_json::from_str(&content)?;
    let entries: Vec<Entry> = parsed.into_iter().collect();
    if let Some(p) = output_pattern {
        // Validate formatter only (discard), matching observed behaviour.
        let _ = Formatter::new(Some(p))?;
    }
    Ok(entries)
}

// ---------- Rename ----------

fn prepend_underscore(output: &mut PathBuf) {
    let file_name = output
        .file_name()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_default();
    output.set_file_name(format!("_{}", file_name));
}

/// Returns (retained_entries, success_flag)
fn do_rename(entries: Vec<Entry>, test: bool, overwrite: bool, mkdir_flag: bool) -> (Vec<Entry>, bool) {
    let mut retained: Vec<Entry> = Vec::new();
    let mut success = true;
    for (input, output_str) in entries {
        let mut output = PathBuf::from(&output_str);
        if !overwrite {
            // while output exists and output != input (Path equality)
            // Loop guard: original loops while exists; if output becomes equal to input (?) could stop
            while output.exists() && output != Path::new(&input) {
                prepend_underscore(&mut output);
            }
        }
        if mkdir_flag {
            if let Some(parent) = output.parent() {
                let _ = fs::create_dir_all(parent);
            }
        }
        let final_output = output.to_string_lossy().into_owned();
        if test {
            retained.push((input, final_output));
        } else {
            match fs::rename(&input, &output) {
                Ok(()) => retained.push((input, final_output)),
                Err(e) => {
                    success = false;
                    eprintln!("[error] unable to rename '{}': {}", input, e);
                }
            }
        }
    }
    (retained, success)
}

// ---------- Table printing ----------

fn display_width(s: &str) -> usize {
    strip_ansi_width(s)
}

/// Width calculation mimicking prettytable-style: strip CSI sequences
/// terminated by 'm' (keeping the ESC char counted as width 1 via unicode_width),
/// then use UnicodeWidthStr::width.
/// Incomplete CSI (no 'm' until end) strips from '[' to end.
fn strip_ansi_width(s: &str) -> usize {
    // Build stripped string: when we see ESC followed by '[', skip until 'm' or end (including 'm'), keep ESC.
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\u{1b}' {
            out.push(c);
            if let Some(&'[') = chars.peek() {
                chars.next(); // '['
                // skip until 'm' inclusive, or end
                for c2 in chars.by_ref() {
                    if c2 == 'm' {
                        break;
                    }
                }
            }
        } else {
            out.push(c);
        }
    }
    UnicodeWidthStr::width(out.as_str())
}

fn cell_lines(s: &str) -> Vec<String> {
    // Rust str::lines(): splits on \n and \r\n, no trailing empty.
    let v: Vec<String> = s.lines().map(|l| l.to_owned()).collect();
    v
}

fn print_table(map: &BTreeMap<String, String>) {
    if map.is_empty() {
        return;
    }
    // rows: (input_lines, output_lines) where key=output, value=input
    let headers = ("Input".to_string(), "Output".to_string());
    let mut rows: Vec<(Vec<String>, Vec<String>)> = Vec::new();
    let mut col0_w = display_width(&headers.0);
    let mut col1_w = display_width(&headers.1);
    for (output, input) in map.iter() {
        let il = cell_lines(input);
        let ol = cell_lines(output);
        for l in &il {
            col0_w = col0_w.max(display_width(l));
        }
        for l in &ol {
            col1_w = col1_w.max(display_width(l));
        }
        rows.push((il, ol));
    }
    let border = format!("+{}+{}+", "-".repeat(col0_w + 2), "-".repeat(col1_w + 2));
    let mut out = String::new();
    out.push_str(&border);
    out.push('\n');
    // header (single line each)
    out.push_str(&format!(
        "| {}{} | {}{} |\n",
        headers.0,
        " ".repeat(col0_w - display_width(&headers.0)),
        headers.1,
        " ".repeat(col1_w - display_width(&headers.1))
    ));
    out.push_str(&border);
    out.push('\n');
    for (il, ol) in &rows {
        let h = std::cmp::max(il.len(), ol.len());
        let h = if h == 0 { 1 } else { h };
        for i in 0..h {
            let a = il.get(i).cloned().unwrap_or_default();
            let b = ol.get(i).cloned().unwrap_or_default();
            out.push_str(&format!(
                "| {}{} | {}{} |\n",
                a,
                " ".repeat(col0_w - display_width(&a)),
                b,
                " ".repeat(col1_w - display_width(&b))
            ));
        }
    }
    out.push_str(&border);
    out.push('\n');
    print!("{}", out);
}

// ---------- Main ----------

fn run() -> AppResult<bool> {
    let argv0 = std::env::args().next().unwrap_or_default();
    let mut opt = parse_opt();

    if let Some(dir) = &opt.dir {
        std::env::set_current_dir(dir)?;
    }

    // Extract source/output: pop last as output, second-last as source; ignore rest.
    let mut positional = std::mem::take(&mut opt.output);
    let output_pattern: Option<String> = positional.pop();
    let source: Option<String> = positional.pop();

    if source.is_some() && (opt.regex.is_some() || opt.sort.is_some() || opt.map.is_some()) {
        return Err(AppError::Msg(
            "optional SOURCE must be used without setting regex, map or sort flags".to_owned(),
        ));
    }

    let entries: Vec<Entry> = if let Some(pattern) = opt.regex.clone().or(source.clone()) {
        get_regex_entries(&pattern, output_pattern.clone(), opt.depth, opt.max_depth, opt.no_extension)?
    } else if let Some(order) = &opt.sort {
        get_sort_entries(order, output_pattern.clone(), opt.no_extension)?
    } else if let Some(map_path) = &opt.map {
        get_map_entries(map_path, output_pattern.clone())?
    } else {
        return Err(AppError::Msg(format!(
            "one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run '{} --help' for more information.",
            argv0
        )));
    };

    let (retained, success) = do_rename(entries, opt.test, opt.overwrite, opt.mkdir);

    // Build BTreeMap<Output, Input> (last wins)
    let mut btree: BTreeMap<String, String> = BTreeMap::new();
    for (input, output) in retained {
        btree.insert(output, input);
    }

    if let Some(gen_path) = &opt.generate {
        let json = serde_json::to_string_pretty(&btree).unwrap();
        fs::write(gen_path, json)?;
    }

    if !opt.quiet {
        print_table(&btree);
    }

    Ok(success)
}

fn main() {
    match run() {
        Ok(true) => {}
        Ok(false) => process::exit(1),
        Err(e) => {
            eprintln!("error: {}", e);
            process::exit(1);
        }
    }
}
